SELECT 
    CAST(
        SUM(CASE WHEN strftime('%Y', CreationDate) = '2010' THEN 1 ELSE 0 END
        ) AS REAL
    ) /
    NULLIF(
        SUM(CASE WHEN strftime('%Y', CreationDate) = '2011' THEN 1 ELSE 0 END
        ), 0
    ) AS ratio_2010_to_2011
FROM votes

SELECT 
    CAST(
        SUM(CASE WHEN substr(CreationDate, 1, 4) = '2010' THEN 1 ELSE 0 END
        ) AS REAL
    ) /
    NULLIF(
        SUM(CASE WHEN substr(CreationDate, 1, 4) = '2011' THEN 1 ELSE 0 END
        ), 0
    ) AS ratio_2010_to_2011
FROM votes
